#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int data; struct Node *next; } Node;

int main(void)
{
    int a[5] = {1, 2, 3, 4, 5};
    Node *head = NULL, *tail = NULL, *p;
    int i;

    for (i = 0; i < 5; i++) {              /* 逻辑上都是同一个线性表 */
        Node *s = (Node *)malloc(sizeof(Node));
        if (s == NULL) return 1;
        s->data = a[i];
        s->next = NULL;
        if (head == NULL) head = s; else tail->next = s;
        tail = s;
    }

    printf("array storage : ");
    for (i = 0; i < 5; i++) printf("%d ", a[i]);

    printf("\nlist  storage : ");
    for (p = head; p != NULL; p = p->next) printf("%d ", p->data);
    printf("\n");

    while (head != NULL) { Node *t = head; head = head->next; free(t); }
    return 0;
}

