#include <stdio.h>

#define CAP 16

/* ---- 存储结构：对使用者应当是隐藏的 ---- */
typedef struct { int data[CAP]; int top; } SeqStack;

/* ---- ADT Stack 的基本操作（接口）---- */
static void stk_init(SeqStack *s)         { s->top = -1; }
static int  stk_empty(const SeqStack *s)  { return s->top == -1; }
static int  stk_full(const SeqStack *s)   { return s->top == CAP - 1; }
static int  stk_push(SeqStack *s, int e)
{
    if (stk_full(s)) return 0;
    s->data[++s->top] = e;
    return 1;
}
static int  stk_pop(SeqStack *s, int *e)
{
    if (stk_empty(s)) return 0;
    *e = s->data[s->top--];
    return 1;
}

/* ---- 使用者：只调用接口，从不写 s.data[s.top] ---- */
int main(void)
{
    SeqStack s;
    int e;

    stk_init(&s);
    stk_push(&s, 10);
    stk_push(&s, 20);
    printf("empty=%d full=%d\n", stk_empty(&s), stk_full(&s));
    while (stk_pop(&s, &e)) printf("pop %d\n", e);
    printf("pop on empty -> %d\n", stk_pop(&s, &e));
    return 0;
}

#include <stdio.h>

static long cnt;

static void f_const(int n)  { (void)n; cnt += 1; }                       /* O(1)    */
static void f_log(int n)    { int i = n; while (i > 0) { cnt++; i /= 2; } } /* O(log n) */
static void f_lin(int n)    { int i; for (i = 0; i < n; i++) cnt++; }     /* O(n)    */
static void f_sqr(int n)    { int i, j;                                   /* O(n^2)  */
                              for (i = 0; i < n; i++)
                                  for (j = 0; j < n; j++) cnt++; }

int main(void)
{
    int ns[4] = {10, 100, 1000, 10000}, k;

    printf("%7s %8s %8s %8s %12s\n", "n", "O(1)", "O(logn)", "O(n)", "O(n^2)");
    for (k = 0; k < 4; k++) {
        int n = ns[k];
        long a, b, c, d;
        cnt = 0; f_const(n);  a = cnt;
        cnt = 0; f_log(n);    b = cnt;
        cnt = 0; f_lin(n);    c = cnt;
        cnt = 0; f_sqr(n);    d = cnt;
        printf("%7d %8ld %8ld %8ld %12ld\n", n, a, b, c, d);
    }
    return 0;
}

#include <stdio.h>

static long calls;

static long fib_rec(int n)                       /* 时间 O(2^n)，空间 O(n) */
{
    calls++;
    if (n <= 1) return n;
    return fib_rec(n - 1) + fib_rec(n - 2);
}

static long fib_loop(int n)                      /* 时间 O(n)，空间 O(1) */
{
    long a = 0, b = 1, t;
    int i;
    if (n <= 1) return n;
    for (i = 2; i <= n; i++) { t = a + b; a = b; b = t; }
    return b;
}

int main(void)
{
    int n = 30;

    calls = 0;
    printf("rec  fib(%d) = %ld  calls = %ld\n", n, fib_rec(n), calls);
    printf("loop fib(%d) = %ld  calls = %ld\n", n, fib_loop(n), 1L);
    return 0;
}
